        for (SubmitMeasurementRequest item : items) {
            ParsedMeasurement parsed = parse(item, defaultSubmitter);
            if (!seenKeys.add(parsed.measurementKey())) {
                throw ApiException.badRequest("批量提交包含重复测量键: " + parsed.measurementKey());
            }
