                    parsed.measurementKey(), parsed.certificate().standardId(),
                    parsed.certificate().version(), parsed.measuredAt(), parsed.instrumentId(),
                    parsed.reading(), parsed.lowerLimit(), parsed.upperLimit(), parsed.submittedBy()));
