                    .contentType(MediaType.APPLICATION_JSON).content(write(Map.of("keys", List.of("DG-1")))))
            .andExpect(status().isOk());
    assertEquals(1, jdbc.queryForObject("SELECT COUNT(*) FROM certificate_batch_binding", Integer.class));
}

